S.append(goals(c,B,['Nêu <b>khái niệm dữ liệu lớn</b> (5V) và khoa học dữ liệu.','Mô tả <b>quy trình</b> khoa học dữ liệu.','<b>Làm sạch</b> và <b>thống kê mô tả</b> dữ liệu bằng Python.','Chọn <b>biểu đồ</b> phù hợp.','Hiểu <b>mô phỏng</b> và ước lượng bằng <b>Monte Carlo</b>.'],['Dữ liệu lớn','Quy trình','Làm sạch, thống kê','Trực quan hoá','Mô phỏng']))
