S.append(TB(c,B+' · 1','Đặc trưng 5V của dữ liệu lớn',['V','Tiếng Anh','Ý nghĩa'],[['<b>Khối lượng</b>','Volume','dung lượng rất lớn (TB, PB)'],['<b>Tốc độ</b>','Velocity','sinh ra và cần xử lí nhanh'],['<b>Đa dạng</b>','Variety','văn bản, ảnh, âm thanh, bảng'],['<b>Độ tin cậy</b>','Veracity','chất lượng, độ chính xác'],['<b>Giá trị</b>','Value','đem lại lợi ích khi khai thác']],note=KEY('Dữ liệu <b>có cấu trúc</b> (bảng), <b>bán cấu trúc</b> (JSON, XML), <b>phi cấu trúc</b> (ảnh, văn bản).')))
S.append(S2(c,B+' · 1','Khoa học dữ liệu là gì?',card('Khái niệm',ul(['Lĩnh vực kết hợp <b>thống kê, lập trình, kiến thức miền</b> để <b>rút ra tri thức</b> từ dữ liệu.','Người làm: <b>nhà khoa học dữ liệu</b>, kĩ sư dữ liệu, nhà phân tích dữ liệu.'],6)),KEY('Ứng dụng: dự báo thời tiết, đề xuất sản phẩm, phát hiện gian lận, quản lí dịch bệnh, nông nghiệp thông minh.')))
S.append(S2(c,B+' · 2','Quy trình khoa học dữ liệu',RES(svg(260,box(10,20,150,50,'1. Đặt câu hỏi','#BBDEFB','#1565C0',18)+box(185,20,150,50,'2. Thu thập','#C8E6C9','#2E7D32',20)+box(360,20,150,50,'3. Làm sạch','#FFF9C4','#F9A825',20)+box(10,160,150,50,'6. Truyền đạt','#BBDEFB','#1565C0',20)+box(185,160,150,50,'5. Mô hình','#C8E6C9','#2E7D32',20)+box(360,160,150,50,'4. Khám phá','#FFF9C4','#F9A825',20)+ar(160,45,185,45)+ar(335,45,360,45)+ar(435,70,435,160)+ar(360,185,335,185)+ar(185,185,160,185)),'6 bước'),card('Ghi nhớ',ul(['Thường <b>lặp lại</b> nhiều vòng.','Làm sạch chiếm khoảng <b>60–80%</b> thời gian.'],6))))
