S.append(PYR(c,B+' · 2','Làm sạch dữ liệu bằng Python','diem = ["8", "7.5", "", "9", "80", "6,5", "7"]\nsach = []\nfor s in diem:\n    s = s.replace(",", ".")\n    if s == "":\n        continue\n    x = float(s)\n    if 0 <= x <= 10:\n        sach.append(x)\nprint(sach)\nprint(len(diem), "->", len(sach))\nprint(round(sum(sach)/len(sach), 2))',KEY('Bỏ ô trống, đổi dấu phẩy thành chấm, <b>loại điểm ngoài [0;10]</b>. Còn 5 giá trị hợp lệ.'),19))
S.append(S2(c,B+' · 3','Thống kê mô tả',card('Các số đặc trưng',ul(['<b>Trung bình</b>: tổng/số lượng.','<b>Trung vị</b>: giá trị giữa khi sắp xếp (ít bị ngoại lai ảnh hưởng).','<b>Yếu vị</b> (mốt): giá trị xuất hiện nhiều nhất.','<b>Độ lệch chuẩn</b>: mức phân tán quanh trung bình.'],6)),KEY('Dữ liệu có <b>ngoại lai</b>: ưu tiên <b>trung vị</b> hơn trung bình.')))
S.append(PYR(c,B+' · 3','Thống kê bằng thư viện statistics','import statistics as st\nd = [5, 6, 7, 7, 8, 9, 10, 30]\nprint(st.mean(d))\nprint(st.median(d))\nprint(st.mode(d))\nprint(round(st.pstdev(d), 2))\nprint(min(d), max(d))',KEY('Giá trị <b>30</b> (ngoại lai) kéo trung bình lên 10,25, còn trung vị vẫn <b>7,5</b>.'),21))
S.append(S2(c,B+' · 3','Tương quan giữa hai đại lượng',card('Khái niệm',ul(['<b>Tương quan dương</b>: x tăng thì y tăng.','<b>Tương quan âm</b>: x tăng thì y giảm.','<b>Không tương quan</b>: không có quy luật.'],6)),KEY('<b>Tương quan không có nghĩa là nhân quả</b>: kem bán nhiều và đuối nước tăng cùng lúc vì <b>cùng do mùa hè</b>, không phải kem gây đuối nước.')+WARN('Luôn nghi ngờ kết luận nhân quả chỉ từ tương quan.')))
S.append(TB(c,B+' · 4','Chọn biểu đồ phù hợp',['Mục đích','Biểu đồ','Ví dụ'],[['So sánh giá trị các nhóm','<b>cột</b> (bar)','điểm TB các lớp'],['Xu hướng theo thời gian','<b>đường</b> (line)','nhiệt độ theo tháng'],['Tỉ lệ thành phần','<b>tròn</b> (pie)','cơ cấu học lực'],['Phân bố một đại lượng','<b>tần suất</b> (histogram)','phân bố điểm thi'],['Quan hệ hai đại lượng','<b>phân tán</b> (scatter)','chiều cao – cân nặng']],note=KEY('Biểu đồ phải có <b>tiêu đề, nhãn trục, đơn vị</b>; tránh làm sai lệch (cắt trục).')))
S.append(PYR(c,B+' · 4','Biểu đồ cột dạng chữ','diem = {"10A": 7.8, "10B": 7.2, "10C": 8.4}\nfor lop, d in diem.items():\n    print(lop, "#" * int(d * 4), d)',KEY('Không cần thư viện: mỗi <b>#</b> là một đơn vị. Với <b>matplotlib</b> dùng <code>plt.bar(lop, diem)</code>.'),22))
