S.append(PYR(c,B+' · 4','Ước lượng π bằng Monte Carlo','import random\nrandom.seed(7)\nfor n in (100, 10000, 200000):\n    trong = 0\n    for _ in range(n):\n        x, y = random.random(), random.random()\n        if x*x + y*y <= 1:\n            trong += 1\n    print(n, 4 * trong / n)',KEY('Số điểm càng lớn, ước lượng càng <b>gần 3,14159</b>.'),21))
S.append(PYR(c,B+' · 4','Mô phỏng tung hai xúc xắc','import random\nrandom.seed(3)\nn = 60000\nd = {s: 0 for s in range(2, 13)}\nfor _ in range(n):\n    d[random.randint(1,6) + random.randint(1,6)] += 1\nfor s in (2, 7, 12):\n    print(s, round(d[s] / n, 3))',KEY('Lí thuyết: P(7) = 6/36 ≈ <b>0,167</b>; P(2) = P(12) = 1/36 ≈ <b>0,028</b>. Mô phỏng cho kết quả gần đúng.'),21))
